-- SafetyTraining v20.052
-- Reconcile live fire-training family created after v20.046.
-- D.M. 2/9/2021 levels 1/3 + update levels 1/2/3; legacy 8h course is intentionally untouched.
-- Official VVF evidence is referenced; SafetyTraining wording/scenarios remain original.

DO $do$
DECLARE r jsonb; c jsonb; v_lu uuid; v_luv uuid; v_course uuid; v_cv uuid; v_module uuid; v_content jsonb;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"k":"fire:l1:combustion","t":"Principi dell’incendio e prevenzione nel luogo di lavoro","s":"Comprendere come nasce e si sviluppa un incendio e quali comportamenti riducono la probabilità di innesco.","m":60,"v":"fire-v2","p":false,"f":["combustione","innesco","combustibili","prevenzione","sorveglianza"],"case":"In un piccolo deposito un caricabatterie scalda vicino a cartoni: individuare combustibile, innesco, misura immediata e segnalazione.","d":"L’addetto di livello 1 deve riconoscere combustibile, comburente e sorgente di innesco e collegarli alle condizioni reali del proprio luogo di lavoro. La prevenzione consiste soprattutto nel tenere sotto controllo fonti di calore, materiali combustibili, ordine, pulizia, lavorazioni a caldo e condizioni anomale. L’addetto non sostituisce manutentori o responsabili: riconosce, segnala e applica le procedure.","pr":["osservare le possibili sorgenti di innesco","mantenere vie di esodo e presidi accessibili","segnalare accumuli combustibili e anomalie","rispettare divieti e procedure per lavori a caldo","conoscere il sistema di allarme e il proprio ruolo"],"e":["pensare che l’incendio inizi solo da fiamma libera","ostruire temporaneamente un estintore o una via di esodo","ignorare odori di surriscaldamento o anomalie elettriche","accumulare materiale vicino a sorgenti di calore"]},
    {"k":"fire:l1:protection","t":"Protezione antincendio, allarme ed evacuazione","s":"Conoscere estintori, segnaletica, vie di esodo e procedure da adottare quando si rileva un incendio.","m":60,"v":"fire-v2","p":false,"f":["estintori","allarme","esodo","segnaletica","chiamata soccorsi"],"case":"Fumo da un cestino vicino a una porta: decidere allarme, posizione sicura, eventuale estintore ed evacuazione.","d":"La risposta corretta parte dall’allarme: avvisare secondo il piano, chiamare i soccorsi se previsto, mettere in sicurezza le persone e usare un estintore solo se l’incendio è iniziale, la via di fuga resta alle spalle e l’addetto è in condizioni di agire senza esporsi. L’evacuazione ha priorità sul tentativo di spegnimento quando il focolaio cresce o il fumo rende l’ambiente non sicuro.","pr":["dare l’allarme secondo procedura","valutare se il focolaio è affrontabile senza esporsi","mantenere sempre disponibile una via di fuga","favorire l’esodo senza creare confusione","raggiungere il punto di raccolta e riferire informazioni utili"],"e":["affrontare un incendio già sviluppato","entrare nel fumo per recuperare oggetti","usare ascensori se il piano non lo consente","tornare nell’edificio senza autorizzazione"]},
    {"k":"fire:l1:practical","t":"Estintori e operazioni pratiche di base","s":"Esercitarsi su controllo visivo, impugnatura, uso dell’estintore e comportamento sicuro.","m":120,"v":"fire-v2","p":true,"f":["presa visione estintori","controllo visivo","uso estintore","allarme","esodo"],"case":"Prova pratica controllata: individuare presidio, descrivere controllo visivo, assumere posizione sicura ed eseguire lo spegnimento didattico.","d":"La pratica deve far vedere e provare i presidi previsti dal D.M. 2 settembre 2021. Il docente mostra i principali estintori disponibili, le indicazioni di utilizzo, la distanza di sicurezza e il criterio di abbandono dell’intervento. Ogni partecipante deve svolgere esercitazioni controllate, con DPI e area predisposta dal formatore.","pr":["riconoscere tipo di estintore e indicazioni","verificare accessibilità e condizioni visive del presidio","avvicinarsi mantenendo una via di fuga","azionare il presidio secondo istruzioni e addestramento","interrompere e allontanarsi se il focolaio non è controllabile"],"e":["mettersi tra incendio e uscita","avvicinarsi troppo","usare acqua su scenari incompatibili","continuare quando fumo o calore aumentano"]},
    {"k":"fire:l3:combustion","t":"Combustione, cause, prodotti e sostanze estinguenti","s":"Approfondire fenomenologia dell’incendio e scelta dell’agente estinguente.","m":120,"v":"fire-v2","p":false,"f":["combustione","sviluppo incendio","prodotti combustione","sostanze estinguenti","rischi persone/ambiente"],"case":"Incendio in area con materiali differenti: confrontare agenti estinguenti possibili e motivare quelli da escludere.","d":"Nel livello 3 l’addetto deve comprendere più a fondo sviluppo dell’incendio, prodotti della combustione, propagazione, effetti sulle persone e sull’ambiente e compatibilità delle sostanze estinguenti con il materiale coinvolto. La conoscenza serve a riconoscere quando un intervento interno è ancora possibile e quando occorre privilegiare isolamento, allarme ed evacuazione.","pr":["riconoscere classe/materiale e scenario","valutare fumo, calore e propagazione","selezionare presidio coerente con scenario e addestramento","mantenere una via di fuga","abbandonare l’intervento se cambia il margine di sicurezza"],"e":["scegliere estinguente solo per abitudine","sottovalutare fumo e prodotti tossici","avvicinarsi oltre il limite sicuro","continuare a intervenire su un incendio non più iniziale"]},
    {"k":"fire:l3:prevention","t":"Cause di incendio, prevenzione e controllo degli ambienti","s":"Riconoscere cause tecniche e organizzative e impostare sorveglianza efficace.","m":120,"v":"fire-v2","p":false,"f":["cause incendio","prevenzione","lavori a caldo","depositi","sorveglianza","manutenzione"],"case":"Sopralluogo simulato con cinque anomalie: classificarle per urgenza e definire chi deve intervenire.","d":"La prevenzione riguarda impianti, lavorazioni a caldo, cariche elettrostatiche, depositi, combustibili, rifiuti, housekeeping, lavori di manutenzione e comportamenti. L’addetto contribuisce alla sorveglianza ma le verifiche/manutenzioni specialistiche restano affidate a soggetti competenti.","pr":["riconoscere condizioni anomale","mantenere segregazione e ordine dei combustibili","controllare che presidi e vie siano accessibili","segnalare manomissioni o guasti","applicare permessi/procedure per attività critiche"],"e":["confondere sorveglianza e manutenzione","tollerare porte tagliafuoco bloccate aperte","accumulare materiali in vie di esodo","ignorare lavori temporanei che introducono inneschi"]},
    {"k":"fire:l3:passive","t":"Reazione, resistenza, compartimentazione ed esodo","s":"Comprendere come le misure passive limitano sviluppo e propagazione e proteggono l’esodo.","m":120,"v":"fire-v2","p":false,"f":["reazione al fuoco","resistenza","compartimentazione","porte tagliafuoco","esodo"],"case":"Una porta tagliafuoco viene bloccata per facilitare il passaggio merci: spiegare rischio e soluzione organizzativa corretta.","d":"Reazione e resistenza al fuoco, compartimentazione e porte resistenti al fuoco lavorano insieme per rallentare la propagazione e mantenere condizioni utili all’esodo. L’addetto deve riconoscere alterazioni evidenti delle misure e non neutralizzarle per comodità.","pr":["mantenere compartimentazioni e porte nella condizione prevista","non ostruire vie e uscite","segnalare danneggiamenti o modifiche","conoscere alternative di esodo previste","impedire riaperture non autorizzate durante emergenza"],"e":["bloccare porte tagliafuoco con cunei","depositare materiali nei corridoi","modificare passaggi senza valutazione","supporre che una porta chiusa sia sempre antincendio certificata"]},
    {"k":"fire:l3:detection","t":"Rivelazione, allarme, controllo fumi e sistemi di sicurezza","s":"Comprendere funzione e limiti dei sistemi attivi di rilevazione e gestione dell’emergenza.","m":120,"v":"fire-v2","p":false,"f":["rivelazione","allarme","EVAC","controllo fumo","alimentazioni sicurezza"],"case":"La centrale segnala guasto in una zona durante attività: definire misura compensativa ed escalation.","d":"Rivelazione automatica, allarme, evacuazione vocale, sistemi di controllo fumo e calore e alimentazioni di sicurezza supportano la risposta ma non eliminano la necessità di procedure, sorveglianza e manutenzione. L’addetto deve sapere cosa osservare e come reagire a un allarme o guasto.","pr":["riconoscere segnalazioni e allarmi","non tacitare senza comprenderne la causa","applicare la procedura per guasto/indisponibilità","mantenere accesso a centrali e comandi","riferire informazioni ai soccorritori"],"e":["resettare ripetutamente un allarme","coprire rivelatori durante lavori senza procedura","ignorare guasti perché il sistema di solito funziona","confondere silenziamento acustico con eliminazione della causa"]},
    {"k":"fire:l3:control","t":"Controllo dell’incendio: estintori, idranti e altri presidi","s":"Conoscere funzione, campo d’impiego e limiti dei presidi di controllo dell’incendio.","m":120,"v":"fire-v2","p":false,"f":["estintori","naspi","idranti","sistemi fissi","limiti operativi"],"case":"Confrontare uso di estintore e idrante in due scenari diversi e definire limiti di intervento.","d":"Estintori, naspi, idranti e altri sistemi hanno obiettivi, portate e modalità d’impiego differenti. L’addetto deve scegliere il presidio coerente con scenario e addestramento, evitare esposizione e garantire che l’intervento non ostacoli esodo o arrivo dei soccorsi.","pr":["identificare presidio disponibile","valutare compatibilità con scenario","coordinarsi con altro addetto quando necessario","mantenere posizione e percorso sicuri","abbandonare l’intervento se non efficace"],"e":["usare un idrante senza comprendere reazione e gestione della tubazione","ostacolare l’esodo con manichette","improvvisare su impianti fissi","ritardare l’allarme per tentare lo spegnimento"]},
    {"k":"fire:l3:gsa","t":"Gestione della sicurezza antincendio in esercizio e in emergenza","s":"Collegare sorveglianza, piano di emergenza, ruoli, assistenza alle persone e rapporti con VVF.","m":120,"v":"fire-v2","p":false,"f":["GSA","piano emergenza","assistenza persone","112/115","registro controlli","rapporti VVF"],"case":"Esercitazione da allarme a punto di raccolta con una persona che necessita assistenza e accesso VVF da predisporre.","d":"La gestione antincendio quotidiana mantiene efficienti le misure previste; in emergenza servono allarme, comando, comunicazioni, esodo, assistenza alle persone con esigenze specifiche, chiamata ai soccorsi e passaggio di informazioni. L’addetto opera entro il piano dell’attività e non improvvisa ruoli.","pr":["conoscere segnali e responsabilità","attuare allarme ed evacuazione","assistere persone secondo piano","fornire ai soccorsi accessi, rischi e informazioni","partecipare a esercitazioni e debriefing"],"e":["ritardare la chiamata aspettando conferma assoluta","tornare a recuperare beni","dare ordini incompatibili con il piano","non aggiornare il piano dopo modifiche organizzative"]},
    {"k":"fire:l3:practical-ext","t":"Pratica: estintori, controlli e spegnimento iniziale","s":"Eseguire controlli e uso sicuro degli estintori in scenari didattici controllati.","m":120,"v":"fire-v2","p":true,"f":["estintori","controllo visivo","prova spegnimento","DPI","criterio abbandono"],"case":"Prova individuale con focolaio didattico e successivo debriefing sulla decisione di intervento.","d":"Ogni partecipante prende visione dei presidi, riconosce componenti e indicazioni, valuta posizione e via di fuga e svolge prova di spegnimento secondo le condizioni predisposte dal formatore. Il docente corregge distanza, posizione, direzione e decisione di interrompere.","pr":["ispezionare visivamente il presidio","identificare scenario compatibile","mantenere via di fuga","eseguire l’azione secondo addestramento","interrompere su segnale o perdita di controllo"],"e":["puntare senza valutare direzione del vento","mettersi con fuga bloccata","avvicinarsi eccessivamente","continuare con estintore esaurito o focolaio crescente"]},
    {"k":"fire:l3:practical-hose","t":"Pratica: naspi, idranti, sorveglianza e scenario integrato","s":"Esercitarsi su sistemi ad acqua e gestione coordinata di un’emergenza compatibile con il livello 3.","m":120,"v":"fire-v2","p":true,"f":["naspi","idranti","manichette","comunicazione","scenario emergenza"],"case":"Scenario finale: allarme, scelta del presidio, gestione in coppia, comunicazione al punto di raccolta e passaggio informazioni.","d":"La pratica include presa visione e manovra di naspi/idranti ove previsti, gestione della tubazione, apertura progressiva, coordinamento tra addetti e scenario integrato con allarme, esodo e comunicazione. L’uso avviene su impianti/attrezzature idonei e sotto controllo del formatore.","pr":["controllare configurazione e accessibilità","stendere senza creare intralci critici","coordinarsi prima dell’apertura","gestire getto e arretramento in sicurezza","chiudere e ripristinare secondo procedura didattica"],"e":["aprire improvvisamente senza coordinamento","attraversare vie di esodo senza gestione","operare da soli quando servono più addetti","usare getti su scenari non compatibili"]},
    {"k":"fire:upd:l1:practice","t":"Aggiornamento pratico Livello 1","s":"Richiamare controlli e uso degli estintori e i comportamenti essenziali in emergenza.","m":120,"v":"fire-update-v2","p":true,"f":["estintori","controllo visivo","uso pratico","allarme","via di fuga"],"case":"Focolaio didattico: ogni corsista sceglie posizione e presidio ed esegue la prova con feedback.","d":"L’aggiornamento di livello 1 è pratico. Si ripassano presa visione degli estintori, istruzioni d’uso, controllo visivo, posizione sicura, prova di spegnimento e decisione di abbandonare l’intervento quando il focolaio non è più gestibile.","pr":["riconoscere il presidio","controllare condizioni visive","mantenere via di fuga","eseguire prova pratica","interrompere se scenario peggiora"],"e":["considerare l’esperienza passata sufficiente senza prova","mettersi tra incendio e uscita","ritardare allarme","continuare oltre il margine sicuro"]},
    {"k":"fire:upd:l2:theory","t":"Aggiornamento Livello 2: incendio, prevenzione e procedure","s":"Aggiornare prevenzione, protezione e procedure partendo da cambiamenti e criticità reali.","m":120,"v":"fire-update-v2","p":false,"f":["prevenzione","protezione","allarme","esodo","GSA","cambiamenti"],"case":"Una via di esodo è stata modificata dopo ristrutturazione: aggiornare comportamento, segnaletica e briefing agli addetti.","d":"Il richiamo teorico non deve essere una ripetizione meccanica: il docente seleziona argomenti del corso iniziale in base a modifiche dell’attività, eventi, manutenzioni, esercitazioni e criticità osservate. Si ripassano incendio/prevenzione, protezione, allarme, esodo e comportamento dell’addetto.","pr":["ricostruire cosa è cambiato dall’ultimo corso","rivedere cause e misure pertinenti","analizzare almeno un evento o quasi evento","ripassare segnali e ruolo nell’emergenza","definire correzioni pratiche"],"e":["lezione solo mnemonica","ignorare modifiche layout/processo","non usare esiti delle prove di evacuazione","confondere addetto con vigile del fuoco"]},
    {"k":"fire:upd:l2:practice","t":"Aggiornamento Livello 2: estintori, naspi e idranti","s":"Rinnovare abilità pratiche su presidi e decisione di intervento.","m":180,"v":"fire-update-v2","p":true,"f":["estintori","naspi","idranti","controlli","comunicazione"],"case":"Scenario pratico in coppia: allarme, scelta del presidio, uso controllato e comunicazione di esito.","d":"Ogni partecipante esegue prove pratiche coerenti con il programma: controllo e uso degli estintori, presa visione e uso di naspi/idranti ove previsti, gestione sicura dell’area e interruzione dell’intervento quando il rischio supera il margine previsto.","pr":["presa visione dei presidi","controllo visivo","prova estintore","prova sistemi ad acqua ove previsti","debriefing su scelta e limiti"],"e":["pratica solo dimostrativa senza coinvolgimento individuale","nessuna via di fuga","intralciare l’esodo","continuare un intervento inefficace"]},
    {"k":"fire:upd:l3:theory1","t":"Aggiornamento Livello 3: incendio, prevenzione e strategia","s":"Aggiornare principi, rischi specifici e misure della strategia antincendio.","m":150,"v":"fire-update-v2","p":false,"f":["cause","rischi specifici","esplosione","misure passive","sistemi attivi"],"case":"Una compartimentazione viene temporaneamente compromessa durante lavori: definire segnalazione e gestione compensativa.","d":"Si selezionano e approfondiscono argomenti del corso 3-FOR in funzione dell’attività: cause, prodotti della combustione, aree a rischio specifico, esplosione, compartimentazione, esodo, rivelazione, controllo fumi e controllo dell’incendio. Il focus è capire ciò che è cambiato e le conseguenze operative.","pr":["identificare modifiche impiantistiche o di processo","rivalutare rischi e presidi collegati","ripassare segnalazioni e guasti critici","analizzare una non conformità reale o simulata","definire misura compensativa quando prevista"],"e":["aggiornare solo teoria generale","ignorare indisponibilità temporanee di sistemi","considerare una modifica di layout irrilevante","tacere un allarme senza indagine"]},
    {"k":"fire:upd:l3:theory2","t":"Aggiornamento Livello 3: GSA, controlli ed emergenza","s":"Rafforzare gestione quotidiana, sorveglianza, procedure ed esercitazioni.","m":150,"v":"fire-update-v2","p":false,"f":["GSA","registro","sorveglianza","piano emergenza","esercitazioni","rapporti soccorsi"],"case":"Dopo un’esercitazione emergono ritardi e un’uscita poco nota: costruire azioni, responsabili e verifica della correzione.","d":"Il modulo ripassa gestione della sicurezza antincendio in esercizio e in emergenza, registro dei controlli, sorveglianza dell’addetto, assistenza, evacuazione e coordinamento con i soccorsi. Si usano gli esiti di esercitazioni e incidenti per migliorare il piano.","pr":["leggere esiti di prove e anomalie","distinguere sorveglianza da manutenzione","verificare accessi e percorsi di esodo","aggiornare ruoli dopo cambi di personale/layout","preparare informazioni per i soccorsi"],"e":["firmare controlli non eseguiti","confondere verifica specialistica e sorveglianza","mantenere un piano non più coerente col layout","chiudere una prova senza debriefing"]},
    {"k":"fire:upd:l3:practice","t":"Aggiornamento Livello 3: esercitazioni su presidi e scenario","s":"Rinnovare abilità pratiche con estintori, sistemi ad acqua e scenario integrato.","m":180,"v":"fire-update-v2","p":true,"f":["estintori","naspi","idranti","DPI","scenario integrato"],"case":"Scenario integrato con squadra: allarme, scelta presidio, esercitazione, stop su variazione introdotta dal docente e passaggio informazioni.","d":"La parte pratica include presa visione e uso degli estintori, sistemi ad acqua e attrezzature pertinenti, sempre con area didattica predisposta e DPI. Il docente osserva non solo la tecnica ma anche scelta del presidio, posizione, comunicazione, interruzione e passaggio dall’intervento all’evacuazione.","pr":["controllare presidio e scenario","mantenere posizione e via di fuga","eseguire prova estintore","gestire sistemi ad acqua in coordinamento","chiudere con scenario e debriefing"],"e":["eseguire gesti senza comprendere il rischio","intralciare l’esodo","aprire idrante senza coordinamento","restare sul focolaio quando l’emergenza evolve"]}
  ]::jsonb) LOOP
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    VALUES(r->>'k',r->>'t',r->>'s',(r->>'m')::int,'SafetyTraining fire-v2',array['safetytraining','fire',r->>'v'],true,
      jsonb_build_object('source_audit',jsonb_build_object('notes','Usare i manuali VVF come riferimento tecnico-didattico; mantenere testi, schemi e scenari SafetyTraining originali.','status','reviewed','checked_on','2026-10-15','reuse_policy','reference_and_original_rewrite','primary_authority','Corpo Nazionale dei Vigili del Fuoco'),'learner_ready',true,'teacher_ready',true,'practical_focus',(r->>'p')::boolean,'didactic_version',r->>'v'))
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;
    v_content := jsonb_build_object('case',r->>'case','norm','D.M. 2 settembre 2021, Allegato III; D.Lgs. 81/2008 artt. 18, 43 e 46; piano di emergenza e misure dell’attività.','quiz',jsonb_build_object('options',jsonb_build_array('Avvicinarsi per finire lo spegnimento','Continuare finché l’estintore è pieno','Interrompere l’intervento, dare/rafforzare l’allarme e portarsi in sicurezza secondo il piano','Aspettare un altro addetto vicino al focolaio'),'question','Quando un focolaio cresce, il fumo aumenta o la via di fuga non è più sicura, cosa deve fare l’addetto?','explanation','L’addetto opera solo entro un margine di sicurezza: un incendio evoluto o una via di fuga compromessa richiedono abbandono dell’intervento ed evacuazione/attivazione dei soccorsi.','correct_index',2),'focus',r->'f','title',r->>'t','detail',r->>'d','minutes',(r->>'m')::int,'quality',jsonb_build_object('learner_ready',true,'teacher_ready',true,'scenario_based',true,'practical_focus',(r->>'p')::boolean),'summary',r->>'s','visuals',jsonb_build_array('piramide-pericoli.svg','procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg'),'procedure',r->'pr','common_errors',r->'e','delivery_note','Il materiale resta consultabile integralmente. Le parti pratiche previste dal programma richiedono esercitazione effettiva e non sono sostituite dalla sola fruizione digitale.','guided_activity',jsonb_build_array('spiegazione o dimostrazione commentata','analisi di uno scenario','decisione/azione del corsista','feedback con spiegazione del rischio','criterio di stop e follow-up'),'didactic_version',r->>'v','evidence_sources',jsonb_build_array(jsonb_build_object('url','https://www.vigilfuoco.it/comando-vvf-napoli/formazione-le-aziende/materiale-didattico-i-corsi-di-formazione-8108','use','technical_didactic_reference','title','Manuali per corsi antincendio Livelli 1, 2 e 3','authority','Corpo Nazionale dei Vigili del Fuoco','checked_on','2026-10-15'),jsonb_build_object('url','https://www.vigilfuoco.it/sites/default/files/2025-08/DM-02-09-21.pdf','use','normative_validation','title','D.M. 2 settembre 2021','authority','Ministero dell''Interno - Vigili del Fuoco','checked_on','2026-10-15')),'final_assessment',false,'teacher_expansion',case when (r->>'p')::boolean then 'Preparare un’area di esercitazione controllata, DPI e presidi conformi. Il docente dimostra, poi fa eseguire individualmente o in squadra. Osservare posizione, via di fuga, scelta del presidio, comunicazione e criterio di abbandono. Non creare esposizioni reali a fumo, calore o pressioni non controllate.' else 'Collegare la spiegazione a planimetria, piano di emergenza, presidi e criticità reali dell’attività. Usare fotografie o schemi per far riconoscere anomalie. Terminare con uno scenario decisionale: allarme, intervento possibile o evacuazione, comunicazione ai soccorsi.' end,'source_integration_note','Contenuti da spiegare con esempi e scenari originali SafetyTraining; le prove pratiche restano esercitazioni reali secondo il DM 2/9/2021 e le indicazioni del Corpo Nazionale VVF.');
    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) VALUES(v_lu,1,'draft',v_content,null) ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'vvf-materiali-antincendio','technical_reference','Manuali e materiali VVF come riferimento tecnico-didattico per spiegazioni, procedure ed esercitazioni.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'comune-milano-materiale-didattico','didactic_benchmark','Benchmark per casi, sequenze operative e modalità di spiegazione; nessuna copia diretta di testi o immagini.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata) VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}') ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on;
  END LOOP;

  FOR c IN SELECT value FROM jsonb_array_elements($courses$
  [
    {"k":"antincendio_l1","t":"Addetto antincendio – Livello 1 – 4h","d":"Formazione iniziale per addetti antincendio in attività di livello 1 secondo D.M. 2 settembre 2021.","m":240,"bp":"fire_level_1","v":"fire-v2","theory":120,"practice":120},
    {"k":"antincendio_l3","t":"Addetto antincendio – Livello 3 – 16h","d":"Formazione iniziale per addetti antincendio in attività di livello 3 secondo D.M. 2 settembre 2021.","m":960,"bp":"fire_level_3","v":"fire-v2","theory":720,"practice":240},
    {"k":"agg_antincendio_l1","t":"Aggiornamento addetto antincendio – Livello 1 – 2h","d":"Aggiornamento quinquennale per addetti antincendio di livello 1: esercitazioni pratiche.","m":120,"bp":"fire_update_1","v":"fire-update-v2","theory":0,"practice":120},
    {"k":"agg_antincendio_l2","t":"Aggiornamento addetto antincendio – Livello 2 – 5h","d":"Aggiornamento quinquennale per addetti antincendio di livello 2: 2 ore richiamo teorico e 3 ore esercitazioni pratiche.","m":300,"bp":"fire_update_2","v":"fire-update-v2","theory":120,"practice":180},
    {"k":"agg_antincendio_l3","t":"Aggiornamento addetto antincendio – Livello 3 – 8h","d":"Aggiornamento quinquennale per addetti antincendio di livello 3: 5 ore richiamo/approfondimento teorico e 3 ore esercitazioni pratiche.","m":480,"bp":"fire_update_3","v":"fire-update-v2","theory":300,"practice":180}
  ]::jsonb) LOOP
    INSERT INTO public.courses(stable_key,title,family,description,nominal_minutes,certification_mode,active,metadata) VALUES(c->>'k',c->>'t','Antincendio',c->>'d',(c->>'m')::int,'internal_learning',true,jsonb_build_object('blueprint_key',c->>'bp','renewal_months',case when c->>'k' like 'agg_%' then 60 else null end,'theory_minutes',(c->>'theory')::int,'didactic_version',c->>'v','regulatory_basis','D.M. 2 settembre 2021, Allegato III','material_complete',true,'practical_minutes',(c->>'practice')::int,'requires_admin_review',true,'learner_catalog_hidden',true,'delivery_rules_are_metadata_only',true)) ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,family=excluded.family,description=excluded.description,nominal_minutes=excluded.nominal_minutes,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_course;
    INSERT INTO public.course_versions(course_id,version_number,status,syllabus_snapshot,normative_snapshot,published_at) VALUES(v_course,1,'draft',jsonb_build_object('total_minutes',(c->>'m')::int,'didactic_version',c->>'v','material_complete',true),jsonb_build_object('basis','D.M. 2 settembre 2021, Allegato III','renewal','5 years for update courses'),null) ON CONFLICT(course_id,version_number) DO UPDATE SET status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot,published_at=null;
  END LOOP;

  FOR c IN SELECT value FROM jsonb_array_elements($modules$
  [
    {"c":"antincendio_l1","mk":"l1-theory","mt":"Incendio e prevenzione – 2h","mp":1,"mm":120,"u":[["fire:l1:combustion",1,false],["fire:l1:protection",2,false]]},{"c":"antincendio_l1","mk":"l1-practice","mt":"Esercitazioni pratiche – 2h","mp":2,"mm":120,"u":[["fire:l1:practical",1,true]]},
    {"c":"antincendio_l3","mk":"l3-fire","mt":"Incendio e prevenzione – 4h","mp":1,"mm":240,"u":[["fire:l3:combustion",1,false],["fire:l3:prevention",2,false]]},{"c":"antincendio_l3","mk":"l3-strategy","mt":"Strategia antincendio – 8h","mp":2,"mm":480,"u":[["fire:l3:passive",1,false],["fire:l3:detection",2,false],["fire:l3:control",3,false],["fire:l3:gsa",4,false]]},{"c":"antincendio_l3","mk":"l3-practice","mt":"Esercitazioni pratiche – 4h","mp":3,"mm":240,"u":[["fire:l3:practical-ext",1,true],["fire:l3:practical-hose",2,true]]},
    {"c":"agg_antincendio_l1","mk":"l1agg","mt":"Aggiornamento pratico – 2h","mp":1,"mm":120,"u":[["fire:upd:l1:practice",1,true]]},
    {"c":"agg_antincendio_l2","mk":"l2agg-theory","mt":"Richiamo teorico – 2h","mp":1,"mm":120,"u":[["fire:upd:l2:theory",1,false]]},{"c":"agg_antincendio_l2","mk":"l2agg-practice","mt":"Esercitazioni pratiche – 3h","mp":2,"mm":180,"u":[["fire:upd:l2:practice",1,true]]},
    {"c":"agg_antincendio_l3","mk":"l3agg-theory","mt":"Richiamo e approfondimento teorico – 5h","mp":1,"mm":300,"u":[["fire:upd:l3:theory1",1,false],["fire:upd:l3:theory2",2,false]]},{"c":"agg_antincendio_l3","mk":"l3agg-practice","mt":"Esercitazioni pratiche – 3h","mp":2,"mm":180,"u":[["fire:upd:l3:practice",1,true]]}
  ]::jsonb) LOOP
    SELECT cv.id INTO v_cv FROM public.course_versions cv JOIN public.courses co ON co.id=cv.course_id WHERE co.stable_key=c->>'c' AND cv.version_number=1;
    INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,c->>'mk',c->>'mt',(c->>'mp')::int,(c->>'mm')::int) ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=excluded.position,nominal_minutes=excluded.nominal_minutes RETURNING id INTO v_module;
    FOR r IN SELECT value FROM jsonb_array_elements(c->'u') LOOP SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>0; INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) VALUES(v_module,v_luv,(r->>1)::int,true,0,true,jsonb_build_object('material_complete',true,'practical_or_guided',(r->>2)::boolean)) ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules; END LOOP;
  END LOOP;
END $do$;
